package strategy

import (
	"context"
	"fmt"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/go-git/go-git/v6"
)

// ManualCommitStrategy implements the manual-commit strategy for session management.
// It stores checkpoints on shadow branches and condenses session logs to a
// permanent sessions branch when the user commits.
type ManualCommitStrategy struct {
	// stateStore manages session state files in .git/entire-sessions/
	stateStore *session.StateStore
	// stateStoreOnce ensures thread-safe lazy initialization
	stateStoreOnce sync.Once
	// stateStoreErr captures any error during initialization
	stateStoreErr error

	// blobFetcher, when set, is passed to the checkpoint store to enable
	// on-demand blob fetching after treeless fetches. Set via SetBlobFetcher.
	blobFetcher checkpoint.BlobFetchFunc
}

// getStateStore returns the session state store, initializing it lazily if needed.
// Thread-safe via sync.Once.
func (s *ManualCommitStrategy) getStateStore(_ context.Context) (*session.StateStore, error) {
	s.stateStoreOnce.Do(func() {
		store, err := session.NewStateStore(context.Background()) //nolint:contextcheck // sync.Once must use background context to avoid caching errors from a cancelled caller context
		if err != nil {
			s.stateStoreErr = fmt.Errorf("failed to create state store: %w", err)
			return
		}
		s.stateStore = store
	})
	return s.stateStore, s.stateStoreErr
}

func (s *ManualCommitStrategy) getCheckpointStore(repo *git.Repository) *checkpoint.GitStore {
	store := checkpoint.NewGitStore(repo)
	if s.blobFetcher != nil {
		store.SetBlobFetcher(s.blobFetcher)
	}
	return store
}

// getCheckpointReadStore returns a checkpoint store for read-only committed
// access. When checkpoints v1.1 is enabled it resolves committed reads against
// the synced v1.1 custom ref; otherwise it behaves like getCheckpointStore.
// Write and read-modify-write paths must keep using getCheckpointStore (v1).
func (s *ManualCommitStrategy) getCheckpointReadStore(ctx context.Context, repo *git.Repository) *checkpoint.GitStore {
	store := checkpoint.NewCommittedReadStore(ctx, repo)
	if s.blobFetcher != nil {
		store.SetBlobFetcher(s.blobFetcher)
	}
	return store
}

// NewManualCommitStrategy creates a new manual-commit strategy instance.
func NewManualCommitStrategy() *ManualCommitStrategy {
	return &ManualCommitStrategy{}
}

// SetBlobFetcher configures on-demand blob fetching for the checkpoint store.
// Must be called before the first checkpoint store access (e.g., before RestoreLogsOnly).
func (s *ManualCommitStrategy) SetBlobFetcher(f checkpoint.BlobFetchFunc) {
	s.blobFetcher = f
}

// HasBlobFetcher reports whether a blob fetcher is configured.
// Used in tests to verify the strategy is properly wired for treeless fetch support.
func (s *ManualCommitStrategy) HasBlobFetcher() bool {
	return s.blobFetcher != nil
}

// ValidateRepository validates that the repository is suitable for this strategy.
func (s *ManualCommitStrategy) ValidateRepository() error {
	repo, err := OpenRepository(context.Background())
	if err != nil {
		return fmt.Errorf("not a git repository: %w", err)
	}
	defer repo.Close()

	_, err = repo.Worktree()
	if err != nil {
		return fmt.Errorf("failed to access worktree: %w", err)
	}

	return nil
}

// ListOrphanedItems returns orphaned items created by the manual-commit strategy.
// This includes:
//   - Shadow branches that weren't auto-cleaned during commit condensation
//   - Session state files with no corresponding checkpoints or shadow branches
func (s *ManualCommitStrategy) ListOrphanedItems(ctx context.Context) ([]CleanupItem, error) {
	var items []CleanupItem

	// Shadow branches (should have been auto-cleaned after condensation)
	branches, err := ListShadowBranches(ctx)
	if err != nil {
		return nil, err
	}
	for _, branch := range branches {
		items = append(items, CleanupItem{
			Type:   CleanupTypeShadowBranch,
			ID:     branch,
			Reason: "shadow branch (should have been auto-cleaned)",
		})
	}

	// Orphaned session states are detected by ListOrphanedSessionStates
	// which is strategy-agnostic (checks both shadow branches and checkpoints)

	return items, nil
}

package cli

// head_checkpoint_flags.go resolves the review/investigation umbrella flags
// for the checkpoint at HEAD. These functions live in the cli package (not the
// review/ subpackage) because they need checkpoint access, and review →
// checkpoint → codex → review would cycle. They are cross-feature: consumed by
// `entire status` and by both the review and investigate re-run guards.

import (
	"context"
	"fmt"
	"log/slog"
	"os/exec"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/trailers"
)

// headCheckpointFlags returns the (HasReview, HasInvestigation, info) triple
// for HEAD's checkpoint. Returns (false, false, "") when there is no
// checkpoint at HEAD or when reading fails (logged via slog Debug).
//
// info is a human-readable string used by status / re-run guards (e.g.
// "checkpoint abc123def456"). It applies to whichever flag is true; callers
// display the appropriate flag's prose around it.
//
// Single lookup: read the Entire-Checkpoint trailer from HEAD, then resolve
// the CheckpointSummary from the v1 metadata branch.
func headCheckpointFlags(ctx context.Context) (hasReview, hasInvestigation bool, info string) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		logging.Debug(ctx, "head checkpoint flags: locate worktree root", slog.String("error", err.Error()))
		return false, false, ""
	}
	execCmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "log", "-1", "--format=%B")
	output, err := execCmd.Output()
	if err != nil {
		logging.Debug(ctx, "head checkpoint flags: read HEAD commit message", slog.String("error", err.Error()))
		return false, false, ""
	}
	cpID, ok := trailers.ParseCheckpoint(string(output))
	if !ok {
		logging.Debug(ctx, "head checkpoint flags: no Entire-Checkpoint trailer on HEAD")
		return false, false, ""
	}
	repo, err := gitrepo.OpenPath(repoRoot)
	if err != nil {
		logging.Debug(ctx, "head checkpoint flags: open repository", slog.String("error", err.Error()))
		return false, false, ""
	}
	defer repo.Close()
	store := checkpoint.NewCommittedReadStore(ctx, repo)
	summary, err := checkpoint.ReadCommittedCheckpoint(ctx, store, cpID)
	if err != nil || summary == nil {
		logging.Debug(ctx, "head checkpoint flags: resolve checkpoint summary",
			slog.String("checkpoint_id", cpID.String()),
			slog.Any("error", err))
		return false, false, ""
	}
	return summary.HasReview, summary.HasInvestigation, fmt.Sprintf("checkpoint %s", cpID)
}

// headHasReviewCheckpoint checks whether HEAD's checkpoint metadata includes
// a review session. Returns (true, infoString) if HasReview is set.
// Thin compatibility wrapper around headCheckpointFlags so existing callers
// (status display, review re-run guard) keep their (bool, string) signature.
func headHasReviewCheckpoint(ctx context.Context) (bool, string) {
	hasReview, _, info := headCheckpointFlags(ctx)
	if !hasReview {
		return false, ""
	}
	return true, info
}

// headHasInvestigateCheckpoint reports whether HEAD's checkpoint has an
// investigation tagged on it. Mirrors headHasReviewCheckpoint for the
// investigation umbrella flag.
func headHasInvestigateCheckpoint(ctx context.Context) (bool, string) {
	_, hasInvestigation, info := headCheckpointFlags(ctx)
	if !hasInvestigation {
		return false, ""
	}
	return true, info
}

