var _ Store = (*GitStore)(nil)

// GitStore provides operations for both temporary and committed checkpoint storage.
// It implements the Store interface by wrapping a git repository.
type GitStore struct {
	repo        *git.Repository
	blobFetcher BlobFetchFunc
	// committedRef is the ref that committed-checkpoint reads resolve against.
	// Defaults to the v1 branch; v1.1 read stores bind it to the local-only
	// custom ref (paths.MetadataRefName). Write paths remain on the v1 branch.
	committedRef plumbing.ReferenceName
}

// defaultCommittedRef is the v1 metadata branch ref used by default.
func defaultCommittedRef() plumbing.ReferenceName {
	return plumbing.NewBranchReferenceName(paths.MetadataBranchName)
}

// NewGitStore creates a new checkpoint store backed by the given git repository.
// Committed reads resolve against the default v1 metadata branch.
func NewGitStore(repo *git.Repository) *GitStore {
	return &GitStore{repo: repo, committedRef: defaultCommittedRef()}
}

// NewGitStoreWithRef creates a checkpoint store whose committed reads resolve
// against committedRef. An empty ref falls back to the default v1 branch.
func NewGitStoreWithRef(repo *git.Repository, committedRef plumbing.ReferenceName) *GitStore {
	if committedRef == "" {
		committedRef = defaultCommittedRef()
	}
	return &GitStore{repo: repo, committedRef: committedRef}
}

// SetBlobFetcher configures the store to automatically fetch missing blobs
// on demand when reading from metadata trees. This is used after treeless
// fetches where tree objects are local but blob objects are not.
func (s *GitStore) SetBlobFetcher(f BlobFetchFunc) {
	s.blobFetcher = f
}

// Repository returns the underlying git repository.
// This is useful for strategies that need direct repository access.
func (s *GitStore) Repository() *git.Repository {
	return s.repo
}

// CommittedRef returns the ref that committed-checkpoint reads resolve against.
func (s *GitStore) CommittedRef() plumbing.ReferenceName {
	return s.committedRef
}

